import {zip,saveFile} from './files.js?v=28';
import {jpegPdf} from './pdf.js?v=28';
import {qrcodegen} from './vendor/qrcodegen.js?v=1';
import {REPORT_DISCLAIMER,REPORT_LINKS} from './module-report-data.js?v=1';
const ns='http://schemas.openxmlformats.org/';
const xml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const col=i=>{let s='';for(i++;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s;};
const fmt=v=>typeof v==='number'?new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:2}).format(v):String(v??'');
export function chartSvg(chart,W=1080,H=420){
 const L=105,R=30,T=65,B=75,values=chart.series.flatMap(s=>s.values),min=Math.min(0,...values),max=Math.max(1,...values),range=max-min||1,y=v=>T+(max-v)/range*(H-T-B);
 let s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'"><rect width="100%" height="100%" fill="white"/>';
 for(let i=0;i<=4;i++){const v=min+range*i/4,yy=y(v);s+='<line x1="'+L+'" x2="'+(W-R)+'" y1="'+yy+'" y2="'+yy+'" stroke="#e1d7c5"/><text x="'+(L-10)+'" y="'+(yy+5)+'" text-anchor="end" font-family="Arial" font-size="16" fill="#574b36">'+xml(fmt(Math.round(v/1000))+' tis.')+'</text>';}
 chart.series.forEach((series,j)=>{
  s+='<text x="'+(L+j*230)+'" y="28" font-family="Arial" font-size="17" fill="'+series.color+'">'+xml(series.name)+'</text>';
  if(chart.type==='bar'){const step=(W-L-R)/chart.categories.length,bw=step*.55;series.values.forEach((v,i)=>{const yy=y(v),zero=y(0);s+='<rect x="'+(L+i*step+(step-bw)/2)+'" y="'+Math.min(yy,zero)+'" width="'+bw+'" height="'+Math.max(1,Math.abs(zero-yy))+'" fill="'+series.color+'"/>';});}
  else{s+='<polyline fill="none" stroke="'+series.color+'" stroke-width="3" points="'+series.values.map((v,i)=>(L+i/Math.max(1,series.values.length-1)*(W-L-R))+','+y(v)).join(' ')+'"/>';}
 });
 const ticks=chart.type==='bar'?chart.categories.map((_,i)=>i):[...new Set([0,Math.floor((chart.categories.length-1)/2),chart.categories.length-1])];
 ticks.forEach(i=>{const x=chart.type==='bar'?L+(i+.5)*(W-L-R)/chart.categories.length:L+i/Math.max(1,chart.categories.length-1)*(W-L-R);s+='<text x="'+x+'" y="'+(H-28)+'" text-anchor="middle" font-family="Arial" font-size="16" fill="#574b36">'+xml(chart.categories[i])+'</text>';});
 return s+'</svg>';
}
export function workbookBytes(report){
 const chart=report.chart,names=['Prehled','Nastaveni','Data','GrafData','Graf','Upozorneni'];
 const rows=[[[report.title],[report.subtitle],['Položka','Hodnota'],...report.summary],[['Nastavení modulu'],['Položka','Hodnota'],...report.settings],[report.headers,...report.rows],[['Rok / kategorie',...chart.series.map(s=>s.name)],...chart.categories.map((v,i)=>[v,...chart.series.map(s=>s.values[i])])],[[chart.title]],[[report.title],...report.notes.map(n=>[n]),['Právní upozornění',report.disclaimer||REPORT_DISCLAIMER],['Web',REPORT_LINKS.website],['Dobrovolná podpora',REPORT_LINKS.support]]];
 const relation=items=>'<Relationships xmlns="'+ns+'package/2006/relationships">'+items.map(([id,type,target])=>'<Relationship Id="'+id+'" Type="'+ns+type+'" Target="'+target+'"/>').join('')+'</Relationships>';
 const files={'_rels/.rels':relation([['rId1','officeDocument/2006/relationships/officeDocument','xl/workbook.xml']]),'xl/workbook.xml':'<workbook xmlns="'+ns+'spreadsheetml/2006/main" xmlns:r="'+ns+'officeDocument/2006/relationships"><sheets>'+names.map((n,i)=>'<sheet name="'+n+'" sheetId="'+(i+1)+'" r:id="rId'+(i+1)+'"/>').join('')+'</sheets></workbook>','xl/_rels/workbook.xml.rels':relation(names.map((n,i)=>['rId'+(i+1),'officeDocument/2006/relationships/worksheet','worksheets/sheet'+(i+1)+'.xml']))};
 rows.forEach((items,i)=>{files['xl/worksheets/sheet'+(i+1)+'.xml']='<worksheet xmlns="'+ns+'spreadsheetml/2006/main" xmlns:r="'+ns+'officeDocument/2006/relationships"><cols><col min="1" max="1" width="48" customWidth="1"/><col min="2" max="20" width="23" customWidth="1"/></cols><sheetData>'+items.map((row,r)=>'<row r="'+(r+1)+'">'+row.map((v,c)=>typeof v==='number'&&Number.isFinite(v)?'<c r="'+col(c)+(r+1)+'"><v>'+v+'</v></c>':'<c r="'+col(c)+(r+1)+'" t="inlineStr"><is><t xml:space="preserve">'+xml(v)+'</t></is></c>').join('')+'</row>').join('')+'</sheetData>'+(i===4?'<drawing r:id="rId1"/>':'')+'</worksheet>';});
 files['xl/worksheets/_rels/sheet5.xml.rels']=relation([['rId1','officeDocument/2006/relationships/drawing','../drawings/drawing1.xml']]);
 files['xl/drawings/drawing1.xml']='<xdr:wsDr xmlns:xdr="'+ns+'drawingml/2006/spreadsheetDrawing" xmlns:a="'+ns+'drawingml/2006/main"><xdr:twoCellAnchor><xdr:from><xdr:col>0</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>2</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:to><xdr:col>12</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>29</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:to><xdr:graphicFrame macro=""><xdr:nvGraphicFramePr><xdr:cNvPr id="2" name="Graf modulu"/><xdr:cNvGraphicFramePr/></xdr:nvGraphicFramePr><xdr:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/></xdr:xfrm><a:graphic><a:graphicData uri="'+ns+'drawingml/2006/chart"><c:chart xmlns:c="'+ns+'drawingml/2006/chart" xmlns:r="'+ns+'officeDocument/2006/relationships" r:id="rId1"/></a:graphicData></a:graphic></xdr:graphicFrame><xdr:clientData/></xdr:twoCellAnchor></xdr:wsDr>';
 files['xl/drawings/_rels/drawing1.xml.rels']=relation([['rId1','officeDocument/2006/relationships/chart','../charts/chart1.xml']]);
 const n=chart.categories.length,cached=chart.categories.map((v,i)=>'<c:pt idx="'+i+'"><c:v>'+xml(v)+'</c:v></c:pt>').join('');
 const series=chart.series.map((s,i)=>'<c:ser><c:idx val="'+i+'"/><c:order val="'+i+'"/><c:tx><c:v>'+xml(s.name)+'</c:v></c:tx><c:spPr><a:solidFill><a:srgbClr val="'+s.color.slice(1)+'"/></a:solidFill><a:ln w="28575"><a:solidFill><a:srgbClr val="'+s.color.slice(1)+'"/></a:solidFill></a:ln></c:spPr><c:cat><c:strRef><c:f>GrafData!$A$2:$A$'+(n+1)+'</c:f><c:strCache><c:ptCount val="'+n+'"/>'+cached+'</c:strCache></c:strRef></c:cat><c:val><c:numRef><c:f>GrafData!$'+col(i+1)+'$2:$'+col(i+1)+'$'+(n+1)+'</c:f><c:numCache><c:formatCode>#,##0.00</c:formatCode><c:ptCount val="'+n+'"/>'+s.values.map((v,k)=>'<c:pt idx="'+k+'"><c:v>'+v+'</c:v></c:pt>').join('')+'</c:numCache></c:numRef></c:val></c:ser>').join('');
 const type=chart.type==='bar'?'barChart':'lineChart';
 files['xl/charts/chart1.xml']='<c:chartSpace xmlns:c="'+ns+'drawingml/2006/chart" xmlns:a="'+ns+'drawingml/2006/main"><c:lang val="cs-CZ"/><c:chart><c:plotArea><c:layout/><c:'+type+'>'+(chart.type==='bar'?'<c:barDir val="col"/><c:grouping val="clustered"/>':'<c:grouping val="standard"/>')+series+'<c:axId val="1"/><c:axId val="2"/></c:'+type+'><c:catAx><c:axId val="1"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:axPos val="b"/><c:tickLblPos val="nextTo"/><c:crossAx val="2"/><c:crosses val="autoZero"/></c:catAx><c:valAx><c:axId val="2"/><c:scaling><c:orientation val="minMax"/></c:scaling><c:axPos val="l"/><c:numFmt formatCode="#,##0" sourceLinked="0"/><c:tickLblPos val="nextTo"/><c:crossAx val="1"/><c:crosses val="autoZero"/><c:crossBetween val="between"/></c:valAx></c:plotArea><c:legend><c:legendPos val="b"/><c:layout/></c:legend><c:plotVisOnly val="1"/></c:chart></c:chartSpace>';
 files['[Content_Types].xml']='<Types xmlns="'+ns+'package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>'+names.map((_,i)=>'<Override PartName="/xl/worksheets/sheet'+(i+1)+'.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>').join('')+'<Override PartName="/xl/drawings/drawing1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/><Override PartName="/xl/charts/chart1.xml" ContentType="application/vnd.openxmlformats-officedocument.drawingml.chart+xml"/></Types>';
 return zip(files);
}
export async function pdfPages(report){
 await document.fonts.ready;
 const pages=[],W=1240,H=1754,M=76,LIMIT=H-105;let canvas,g,y;
 const text=(s,x,yy,size=21,bold=false,color='#292013')=>{g.font=(bold?'700 ':'400 ')+size+'px Arial';g.fillStyle=color;g.fillText(String(s),x,yy);};
 const page=title=>{canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;g=canvas.getContext('2d');if(!g)throw Error('Canvas není dostupný');g.fillStyle='#fff';g.fillRect(0,0,W,H);text('MŮJ-DIP · Jiří Janoušek',M,70,24,true);g.fillStyle='#c6a15c';g.fillRect(M,95,W-2*M,3);text(title,M,145,29,true);text('Orientační model · '+(pages.length+1),M,H-45,18,false,'#746349');pages.push(canvas);y=200;};
 const ensure=h=>{if(y+h>LIMIT)page(report.title+' · pokračování');};
 const lines=(s,width,size=21)=>{g.font='400 '+size+'px Arial';const words=String(s).split(/\s+/).flatMap(w=>{const out=[];while(g.measureText(w).width>width&&w.length>1){let k=w.length-1;while(k>1&&g.measureText(w.slice(0,k)).width>width)k--;out.push(w.slice(0,k));w=w.slice(k);}return [...out,w];});const out=[];let line='';for(const w of words){if(line&&g.measureText(line+' '+w).width>width){out.push(line);line=w;}else line+=(line?' ':'')+w;}if(line)out.push(line);return out;};
 const para=(s,size=21)=>{for(const line of lines(s,W-2*M,size)){ensure(size*1.5);text(line,M,y,size);y+=size*1.5;}y+=14;};
 const table=(heads,rows,title)=>{if(title){ensure(80);text(title,M,y,25,true);y+=45;}const widths=heads.length===2?[Math.round((W-2*M)*.64),Math.round((W-2*M)*.36)]:heads.map(()=>Math.floor((W-2*M)/heads.length));const row=(vals,header=false)=>{const cells=vals.map((v,i)=>lines(fmt(v),widths[i]-20,header?18:19)),h=Math.max(...cells.map(a=>a.length))*27+18;ensure(h);if(header){g.fillStyle='#f3e7c8';g.fillRect(M,y-22,W-2*M,h);}let x=M;cells.forEach((ls,i)=>{ls.forEach((s,j)=>text(s,x+6,y+j*27,header?18:19,header));x+=widths[i];});g.strokeStyle='#e2d7c4';g.beginPath();g.moveTo(M,y+h-30);g.lineTo(W-M,y+h-30);g.stroke();y+=h;};row(heads,true);for(const vals of rows){if(y+Math.max(...vals.map((v,i)=>lines(fmt(v),widths[i]-20,19).length))*27+18>LIMIT){page(report.title+' · pokračování');row(heads,true);}row(vals);}y+=20;};
 page(report.title);para(report.subtitle);para('Vytvořeno '+new Date().toLocaleDateString('cs-CZ')+'.');table(['Položka','Hodnota'],report.summary,'Modelové výsledky');
 ensure(490);text(report.chart.title,M,y,23,true);y+=24;
 const image=new Image(),url=URL.createObjectURL(new Blob([chartSvg(report.chart,W-2*M,420)],{type:'image/svg+xml'}));try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=reject;image.src=url;});g.drawImage(image,M,y,W-2*M,420);y+=455;}finally{URL.revokeObjectURL(url);}
 page(report.title+' · nastavení');table(['Parametr','Hodnota'],report.settings);for(const note of report.notes)para(note);
 for(let offset=1;offset<report.headers.length;offset+=4){page(report.title+' · data');const indices=[0,...Array.from({length:Math.min(4,report.headers.length-offset)},(_,i)=>offset+i)];table(indices.map(i=>report.headers[i]),report.rows.map(row=>indices.map(i=>row[i])));}
 page('Web, dobrovolná podpora a právní upozornění');
 const qr=(url,x,title)=>{text(title,x,y,23,true);const q=qrcodegen.QrCode.encodeText(url,qrcodegen.QrCode.Ecc.MEDIUM),side=288,border=32,scale=(side-2*border)/q.size;g.fillStyle='#fff';g.fillRect(x,y+25,side,side);g.fillStyle='#000';for(let r=0;r<q.size;r++)for(let c=0;c<q.size;c++)if(q.getModule(c,r))g.fillRect(x+border+c*scale,y+25+border+r*scale,scale,scale);const urlLines=lines(url,500,18);urlLines.forEach((line,i)=>text(line,x,y+side+60+i*25,18));return side+105+urlLines.length*25;};
 const used=Math.max(qr(REPORT_LINKS.website,M,'Otevřít aplikaci'),qr(REPORT_LINKS.support,650,'Dobrovolně podpořit aplikaci'));y+=used;para('QR podpory otevře stránku dobrovolného příspěvku. Platbu potvrzujete až ve svém bankovnictví.',20);
 g.fillStyle='#b99a61';g.fillRect(M,y,W-2*M,2);y+=42;text('Právní upozornění',M,y,25,true);y+=42;para(report.disclaimer||REPORT_DISCLAIMER,20);
 return pages;
}
export async function exportModule(report,format='pdf'){
 if(format==='xlsx'){saveFile('MUJ-DIP-'+report.id+'.xlsx',workbookBytes(report),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');return;}
 const pages=await pdfPages(report),images=pages.map(p=>Uint8Array.from(atob(p.toDataURL('image/jpeg',.95).split(',')[1]),c=>c.charCodeAt(0)));
 saveFile('MUJ-DIP-'+report.id+'.pdf',jpegPdf(images),'application/pdf');
}
